/*
 * Image-diff viewer.
 *
 * Progressive enhancement: the markup in the page is a plain <figure> with the
 * before/after images visible and captioned. If this script never runs — JS off,
 * a load error, a feed reader — the reader still sees both images side by side
 * and loses nothing but the interaction.
 *
 * Slider, onion and blink are pure CSS/DOM over the two source images; only
 * difference, heatmap and highlight need artifacts generated by
 * scripts/image_diff.py.
 */
(function () {
  "use strict";

  var MODES = [
    ["slider", "Slider"],
    ["onion", "Onion"],
    ["blink", "Blink"],
    ["side", "Side by side"],
    ["difference", "Difference"],
    ["heatmap", "Heatmap"],
    ["highlight", "Highlight"],
  ];

  function build(root) {
    if (root.dataset.enhanced) return;
    root.dataset.enhanced = "1";

    var src = {
      before: root.dataset.before,
      after: root.dataset.after,
      difference: root.dataset.difference,
      heatmap: root.dataset.heatmap,
      highlight: root.dataset.highlight,
    };
    var labels = {
      before: root.dataset.beforeLabel || "Before",
      after: root.dataset.afterLabel || "After",
    };

    root.textContent = "";
    root.classList.add("imgdiff--ready");

    var tabs = document.createElement("div");
    tabs.className = "imgdiff__tabs";
    tabs.setAttribute("role", "tablist");

    var stage = document.createElement("div");
    stage.className = "imgdiff__stage";

    var note = document.createElement("p");
    note.className = "imgdiff__note";

    // One <img> per layer, stacked. Swapping modes toggles classes rather than
    // swapping src, so nothing re-downloads and mode changes are instant.
    function layer(name, cls) {
      if (!src[name]) return null;
      var img = document.createElement("img");
      img.src = src[name];
      img.alt = "";
      img.className = "imgdiff__layer " + cls;
      img.draggable = false;
      stage.appendChild(img);
      return img;
    }

    var elBefore = layer("before", "is-before");
    var elAfter = layer("after", "is-after");
    // Each generated layer needs BOTH classes: `is-generated` hides them all by
    // default, `is-<name>` is what the per-mode rule re-reveals.
    layer("difference", "is-generated is-difference");
    layer("heatmap", "is-generated is-heatmap");
    layer("highlight", "is-generated is-highlight");

    // The wipe handle, used by slider mode only.
    var handle = document.createElement("div");
    handle.className = "imgdiff__handle";
    handle.innerHTML = '<span class="imgdiff__grip" aria-hidden="true"></span>';
    stage.appendChild(handle);

    // Corner captions so you always know which image you are looking at.
    var tagA = document.createElement("span");
    tagA.className = "imgdiff__tag imgdiff__tag--a";
    tagA.textContent = labels.before;
    var tagB = document.createElement("span");
    tagB.className = "imgdiff__tag imgdiff__tag--b";
    tagB.textContent = labels.after;
    stage.appendChild(tagA);
    stage.appendChild(tagB);

    var range = document.createElement("input");
    range.type = "range";
    range.min = "0";
    range.max = "100";
    range.value = "50";
    range.className = "imgdiff__range";
    range.setAttribute("aria-label", "Comparison position");

    var blinkTimer = null;
    var mode = "slider";

    function setPosition(pct) {
      root.style.setProperty("--imgdiff-pos", pct + "%");
      // In onion mode the same control drives opacity instead of a clip.
      root.style.setProperty("--imgdiff-opacity", pct / 100);
    }

    function setMode(next) {
      mode = next;
      root.dataset.mode = next;
      Array.prototype.forEach.call(tabs.children, function (b) {
        var on = b.dataset.mode === next;
        b.classList.toggle("is-active", on);
        b.setAttribute("aria-selected", on ? "true" : "false");
        b.tabIndex = on ? 0 : -1;
      });

      if (blinkTimer) {
        clearInterval(blinkTimer);
        blinkTimer = null;
      }
      if (next === "blink") {
        // Deliberately slow. Fast blinking is both unreadable and a
        // photosensitivity hazard; ~1.2s lets the eye settle on each frame.
        var showing = false;
        blinkTimer = setInterval(function () {
          showing = !showing;
          root.classList.toggle("is-blink-after", showing);
        }, 1200);
      } else {
        root.classList.remove("is-blink-after");
      }

      range.hidden = !(next === "slider" || next === "onion");
      note.textContent = NOTES[next] || "";
    }

    var NOTES = {
      slider: "Drag the handle, or use the slider. Best for spotting whether something moved.",
      onion: "Cross-fade between the two. Best for small shifts in position or weight.",
      blink: "Alternates automatically. The eye is very good at catching what flickers.",
      side: "Both at once. Best when you already know where to look.",
      difference: "Raw |before − after|, amplified 3×. Shows texture, including noise.",
      heatmap: "Perceptual ΔE in CIELAB. Warmer means a bigger perceived change.",
      highlight: "Changed regions boxed and ranked by area × severity; everything else dimmed.",
    };

    MODES.forEach(function (entry) {
      var id = entry[0];
      if ((id === "difference" && !src.difference) ||
          (id === "heatmap" && !src.heatmap) ||
          (id === "highlight" && !src.highlight)) return;
      var button = document.createElement("button");
      button.type = "button";
      button.className = "imgdiff__tab";
      button.dataset.mode = id;
      button.textContent = entry[1];
      button.setAttribute("role", "tab");
      button.addEventListener("click", function () { setMode(id); });
      tabs.appendChild(button);
    });

    // Dragging anywhere on the stage moves the wipe, which is what people try
    // first — the handle alone is a small target on a phone.
    function pointerPosition(event) {
      var box = stage.getBoundingClientRect();
      var x = (event.touches ? event.touches[0].clientX : event.clientX) - box.left;
      var pct = Math.max(0, Math.min(100, (x / box.width) * 100));
      range.value = String(pct);
      setPosition(pct);
    }
    var dragging = false;
    stage.addEventListener("pointerdown", function (e) {
      if (mode !== "slider" && mode !== "onion") return;
      dragging = true;
      stage.setPointerCapture(e.pointerId);
      pointerPosition(e);
    });
    stage.addEventListener("pointermove", function (e) { if (dragging) pointerPosition(e); });
    stage.addEventListener("pointerup", function () { dragging = false; });
    stage.addEventListener("pointercancel", function () { dragging = false; });
    range.addEventListener("input", function () { setPosition(Number(range.value)); });

    // Arrow keys on the tablist, as expected for role="tablist".
    tabs.addEventListener("keydown", function (e) {
      var order = Array.prototype.slice.call(tabs.children);
      var index = order.findIndex(function (b) { return b.classList.contains("is-active"); });
      if (e.key === "ArrowRight") index = (index + 1) % order.length;
      else if (e.key === "ArrowLeft") index = (index - 1 + order.length) % order.length;
      else return;
      e.preventDefault();
      setMode(order[index].dataset.mode);
      order[index].focus();
    });

    root.appendChild(tabs);
    root.appendChild(stage);
    root.appendChild(range);
    root.appendChild(note);

    setPosition(50);
    setMode("slider");
  }

  function init() {
    document.querySelectorAll(".imgdiff").forEach(build);
  }

  document.addEventListener("DOMContentLoaded", init);
  // Material's instant navigation swaps content without a page load.
  if (window.document$ && typeof window.document$.subscribe === "function") {
    window.document$.subscribe(init);
  }
})();
